self.onmessage=({data})=>{try{const {start,freq,interval,count}=data;if(typeof start!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(start)||!['daily','weekly','monthly'].includes(freq)||!Number.isInteger(interval)||interval<1||interval>52||!Number.isInteger(count)||count<1||count>50)throw Error('输入参数无效');const date=new Date(start+'T00:00:00.000Z');if(!Number.isFinite(+date)||date.toISOString().slice(0,10)!==start||date.getUTCFullYear()<1901||date.getUTCFullYear()>2099)throw Error('需要1901–2099年真实日期');importScripts('/vendor/rrule/rrule.js');if(typeof rrule?.RRule!=='function')throw Error('日期组件未加载');const R=rrule.RRule,upper=new Date('2099-12-31T00:00:00.000Z');const rule=new R({freq:{daily:R.DAILY,weekly:R.WEEKLY,monthly:R.MONTHLY}[freq],dtstart:date,interval,count,until:upper},true);const results=rule.all((d,i)=>i<50&&d<=upper);const dates=results.map(d=>{if(!Number.isFinite(+d)||d.getUTCHours()||d.getUTCMinutes()||d.getUTCSeconds()||d.getUTCMilliseconds()||d<date||d>upper)throw Error('输出日期越界');return d.toISOString().slice(0,10);});if(dates.length>count||new Set(dates).size!==dates.length||dates.some((d,i)=>i&&d<=dates[i-1]))throw Error('输出顺序校验失败');postMessage({ok:true,dates});}catch(e){postMessage({ok:false,error:e instanceof Error?e.message:'日期生成失败'});}};
